package jsesh.model.unicode;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;

/// Data extracted from the Unicode Egyptian Hieroglyph Database (Unikemet, UAX #57) and from
/// `StandardizedVariants.txt`.
///
/// It provides the standardized variation sequences for rotations. The resource
/// `rotation-variants.txt` is generated by
/// `00_Documents/tools/extract_unikemet.py`. The data is a global, immutable piece of
/// information, hence the singleton.
public enum UnikemetData {
    INSTANCE;

    private final Set<Long> variants = new HashSet<>();

    private UnikemetData() {
        readTable("rotation-variants.txt",
                (cp, value) -> variants.add(key(cp, Integer.parseInt(value, 16))));
    }

    private interface LineConsumer {
        void accept(int codePoint, String value);
    }

    private void readTable(String name, LineConsumer consumer) {
        try (InputStream in = UnikemetData.class.getResourceAsStream(name);
                BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String l;
            while ((l = r.readLine()) != null) {
                if (l.isEmpty() || l.startsWith("#")) {
                    continue;
                }
                String[] fields = l.split("\t");
                consumer.accept(Integer.parseInt(fields[0], 16), fields[1]);
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static long key(int codePoint, int variationSelector) {
        return ((long) codePoint << 32) | variationSelector;
    }

    /// Is there a standardized variation sequence for this sign and this selector?
    ///
    /// @param codePoint the sign's code point.
    /// @param variationSelector the selector's code point (U+FE00...).
    public boolean hasVariationSequence(int codePoint, int variationSelector) {
        return variants.contains(key(codePoint, variationSelector));
    }
}
